+/// What a `[[package]]` rule's `match` names: one package, or every package whose name fits a glob.
+#[derive(Clone, Debug)]
+pub enum PackageMatch {
+    /// `ecosystem/name`: the package's own name in that ecosystem.
+    Exact(PackageId),
+    Glob(PackagePattern),
