+    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
+        match self {
+            Self::Exact(id) => id.fmt(f),
+            Self::Glob(pattern) => pattern.fmt(f),
+        }
+    }
